// ============================================================
// REGULATORY COMPLIANCE ENGINE v3.1 (OPTIMIZED - BATCH MODE)
// Outputs: Individual compliance results + 1 Batch Summary
// Now includes all alert metadata fields inside the Code node!
// ============================================================

const procurementItems = $('Edit Fields - Enrich Audit Metadata').all();
const regulatoryRules = $('Fetch Regulatory Rules').all();
const workflowConfig = (procurementItems[0] && procurementItems[0].json) || {};
const results = [];
let totalViolations = 0;
let criticalCount = 0;
let highCount = 0;

// Setup timestamps
const now = new Date();
const todayStr = now.toISOString().split('T')[0];
const todayNoDash = todayStr.replace(/-/g, '');
const detectedDate = now.toISOString().replace('T', ' ').substring(0, 19);

for (const item of procurementItems) {
  const rec = item.json;
  const violations = [];
  let riskScore = 0;

  for (const ruleItem of regulatoryRules) {
    const rule = ruleItem.json;

    // ---- GDPR / Data Protection ----
    if (rule.rule_category === 'Data Protection' && rec.data_processing_involved === 'Yes') {
      if (!rec.dpa_signed || rec.dpa_signed === 'No') {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: 'DPA not signed for supplier ' + rec.supplier_name,
          severity: rule.severity,
          remediation: rule.required_documentation,
          penalty: rule.penalty_description
        });
        riskScore += rule.severity === 'Critical' ? 35 : 20;
      }
    }

    // ---- Financial Compliance / SOX ----
    if (rule.rule_category === 'Financial Compliance' && rule.threshold_value) {
      const contractVal = parseFloat(rec.contract_value) || 0;
      const threshold = parseFloat(rule.threshold_value) || 0;
      if (contractVal > threshold && (!rec.board_approval || rec.board_approval === 'No')) {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: 'Contract ' + rec.currency + ' ' + rec.contract_value + ' exceeds ' + rule.threshold_type + ' ' + rule.threshold_value + ' without board approval',
          severity: rule.severity,
          remediation: rule.required_documentation,
          penalty: rule.penalty_description
        });
        riskScore += 25;
      }
    }

    // ---- Labor Law / Modern Slavery ----
    if (rule.rule_category === 'Labor Law') {
      if ((rec.worker_category === 'Contractor' || rec.worker_category === 'Outsourced') &&
          (!rec.labor_compliance_cert || rec.labor_compliance_cert === 'No')) {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: rec.supplier_name + ' uses ' + rec.worker_category + ' workers without labor cert',
          severity: rule.severity,
          remediation: rule.required_documentation,
          penalty: rule.penalty_description
        });
        riskScore += rule.severity === 'Critical' ? 30 : 15;
      }
    }

    // ---- Anti-Bribery / FCPA ----
    if (rule.rule_category === 'Anti-Bribery') {
      const highRisk = (workflowConfig.high_risk_countries || 'India,China,Brazil,Nigeria,Russia,Mexico,Indonesia').split(',').map(function(c) { return c.trim(); });
      if (highRisk.includes(rec.supplier_country) &&
          (!rec.antibribery_declaration || rec.antibribery_declaration === 'No')) {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: 'High-risk supplier ' + rec.supplier_name + ' (' + rec.supplier_country + ') missing ABC declaration',
          severity: rule.severity,
          remediation: rule.required_documentation,
          penalty: rule.penalty_description
        });
        riskScore += 20;
      }
    }

    // ---- Contract Expiry ----
    if (rule.rule_category === 'Contract Management' && rec.contract_end_date) {
      const endDate = new Date(rec.contract_end_date);
      const daysLeft = Math.floor((endDate - now) / (1000 * 60 * 60 * 24));
      if (daysLeft < 0) {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: 'Contract expired ' + Math.abs(daysLeft) + ' days ago',
          severity: 'Critical',
          remediation: 'Immediate contract renewal or termination',
          penalty: rule.penalty_description
        });
        riskScore += 35;
      } else if (daysLeft < 30) {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: 'Contract expiring in ' + daysLeft + ' days',
          severity: 'Medium',
          remediation: 'Initiate renewal immediately',
          penalty: 'Service disruption risk'
        });
        riskScore += 10;
      }
    }

    // ---- Due Diligence ----
    if (rule.rule_category === 'Due Diligence') {
      if (parseFloat(rec.contract_value) > (parseFloat(workflowConfig.due_diligence_threshold_usd) || 50000) &&
          (!rec.due_diligence_completed || rec.due_diligence_completed === 'No')) {
        violations.push({
          rule_id: rule.rule_id,
          regulation: rule.regulation_name,
          violation: 'Due diligence not done for ' + rec.currency + ' ' + rec.contract_value + ' contract',
          severity: rule.severity,
          remediation: rule.required_documentation,
          penalty: rule.penalty_description
        });
        riskScore += 15;
      }
    }
  }

  riskScore = Math.min(riskScore, 100);
  let riskLevel = riskScore >= 70 ? 'Critical' : riskScore >= 40 ? 'High' : riskScore > 0 ? 'Medium' : 'Low';
  const status = violations.length === 0 ? 'Compliant' : 'Non-Compliant';

  if (status === 'Non-Compliant') {
    if (riskLevel === 'Critical') criticalCount++;
    else highCount++;
  }
  totalViolations += violations.length;

  // Calculate SLA Deadline
  let slaDays = riskLevel === 'Critical' ? (parseInt(workflowConfig.sla_days_critical) || 7) : riskLevel === 'High' ? (parseInt(workflowConfig.sla_days_high) || 14) : (parseInt(workflowConfig.sla_days_medium) || 30);
  let slaDate = new Date(now.getTime() + slaDays * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  results.push({
    json: {
      item_type: 'individual',
      audit_id: rec.audit_id,
      audit_timestamp: rec.audit_timestamp,
      review_period: rec.review_period,
      transaction_id: rec.transaction_id,
      supplier_name: rec.supplier_name,
      supplier_country: rec.supplier_country,
      contract_value: rec.contract_value,
      currency: rec.currency,
      contract_start_date: rec.contract_start_date,
      contract_end_date: rec.contract_end_date,
      procurement_category: rec.procurement_category,
      department: rec.department,
      approver: rec.approver,
      compliance_status: status,
      violation_count: violations.length,
      risk_score: riskScore,
      risk_level: riskLevel,
      violations_summary: violations.map(function(v) {
        return '[' + v.severity + '] ' + v.regulation + ': ' + v.violation;
      }).join(' | '),
      remediation_steps: Array.from(new Set(violations.map(function(v) { return v.remediation; }))).join(' | '),
      penalties_exposure: Array.from(new Set(violations.map(function(v) { return v.penalty; }))).join(' | '),

      // ALL ALERT METADATA FIELDS ARE NOW COMPUTED HERE!
      priority_flag: riskLevel === 'Critical' ? 'P1 - URGENT' : riskLevel === 'High' ? 'P2 - HIGH' : riskLevel === 'Medium' ? 'P3 - MEDIUM' : 'P4 - LOW',
      escalation_required: riskScore >= 50 ? 'Yes' : 'No',
      sla_deadline: slaDate,
      alert_id: 'ALERT-' + todayNoDash + '-' + rec.transaction_id,
      status: 'Open',
      assigned_to: (rec.department || 'General') + ' Compliance Lead',
      detected_date: detectedDate
    }
  });
}

// ============================================================
// BATCH SUMMARY (1 extra item for the LLM)
// ============================================================
const nonCompliant = results.filter(function(r) {
  return r.json.compliance_status === 'Non-Compliant';
});
const compliant = results.filter(function(r) {
  return r.json.compliance_status === 'Compliant';
});

const batchViolationsText = nonCompliant.map(function(r) {
  return '### ' + r.json.transaction_id + ' - ' + r.json.supplier_name + ' (' + r.json.supplier_country + ')\n' +
    '- Contract: ' + r.json.currency + ' ' + r.json.contract_value + '\n' +
    '- Risk: ' + r.json.risk_score + '/100 (' + r.json.risk_level + ')\n' +
    '- Violations: ' + r.json.violations_summary + '\n' +
    '- Remediation: ' + r.json.remediation_steps;
}).join('\n\n');

const batchRemediationList = Array.from(new Set(
  nonCompliant.flatMap(function(r) {
    return (r.json.remediation_steps || '').split(' | ');
  })
)).filter(function(v) { return v; }).join('\n- ');

const topRiskSuppliers = nonCompliant
  .sort(function(a, b) { return b.json.risk_score - a.json.risk_score; })
  .slice(0, 5)
  .map(function(r) {
    return r.json.supplier_name + ' (Risk: ' + r.json.risk_score + ', ' + r.json.violation_count + ' violations)';
  }).join('\n- ');

results.push({
  json: {
    item_type: 'batch_summary',
    audit_id: 'BATCH-' + todayNoDash,
    audit_timestamp: now.toISOString(),
    review_period: results[0] ? results[0].json.review_period : 'N/A',
    total_transactions: procurementItems.length,
    compliant_count: compliant.length,
    non_compliant_count: nonCompliant.length,
    compliance_rate: Math.round((compliant.length / (procurementItems.length || 1)) * 100) + '%',
    total_violations: totalViolations,
    critical_risk_count: criticalCount,
    high_risk_count: highCount,
    top_risk_suppliers: topRiskSuppliers || 'None',
    all_violations_text: batchViolationsText || 'None',
    all_remediation_needed: batchRemediationList || 'None',
    contract_value_at_risk: nonCompliant.reduce(function(sum, r) {
      return sum + (parseFloat(r.json.contract_value) || 0);
    }, 0),
    compliance_status: nonCompliant.length > 0 ? 'Non-Compliant' : 'Compliant',
    risk_level: criticalCount > 0 ? 'Critical' : highCount > 0 ? 'High' : 'Low',
    risk_score: Math.min(Math.round((nonCompliant.length / (procurementItems.length || 1)) * 100), 100)
  }
});

return results;

